import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { authApi } from '../api/client';
import Toast from '../components/Toast';
import {
  Mail,
  Lock,
  Eye,
  EyeOff,
  LogIn,
  Activity,
  Sparkles,
  Radio,
  ShieldCheck,
  ArrowRight,
  Key,
} from 'lucide-react';

const LoginPage = ({ onLoginSuccess }) => {
  const navigate = useNavigate();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(true);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      setToast({ message: 'Please enter both your email address and password.', type: 'error' });
      return;
    }

    try {
      setLoading(true);
      const res = await authApi.login({ email, password });

      if (res.data.success) {
        localStorage.setItem('token', res.data.token);
        localStorage.setItem('user', JSON.stringify(res.data.user));

        if (onLoginSuccess) onLoginSuccess(res.data.user);
        setToast({ message: `Welcome back, ${res.data.user.name || 'User'}! Redirecting to workspace...`, type: 'success' });
        setTimeout(() => navigate('/'), 500);
      }
    } catch (err) {
      const msg = err.response?.data?.message || 'Authentication failed. Please check your credentials.';
      setToast({ message: msg, type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleSsoClick = () => {
    setToast({
      message: 'Single Sign-On (SSO) is enabled for Enterprise SAML/OAuth2 domains.',
      type: 'info',
    });
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        width: '100vw',
        display: 'flex',
        background: '#F8FAFC',
        fontFamily: "'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif",
        overflowX: 'hidden',
      }}
    >
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      <style>{`
        @keyframes fadeInPage {
          from { opacity: 0; transform: translateY(6px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .login-fade-in {
          animation: fadeInPage 0.45s ease-out forwards;
        }
        .enterprise-input {
          width: 100%;
          padding: 0.75rem 1rem 0.75rem 2.6rem;
          background: #ffffff;
          border: 1.5px solid #E5E7EB;
          border-radius: 8px;
          font-size: 0.9rem;
          font-weight: 600;
          color: #0F172A;
          transition: all 0.2s ease;
          outline: none;
        }
        .enterprise-input:focus {
          border-color: #2563EB;
          box-shadow: 0 0 0 3.5px rgba(37, 99, 235, 0.12);
        }
        .enterprise-input-icon {
          position: absolute;
          left: 0.85rem;
          top: 50%;
          transform: translateY(-50%);
          color: #64748B;
          pointer-events: none;
        }
        .primary-submit-btn {
          width: 100%;
          padding: 0.85rem 1.5rem;
          background: #2563EB;
          color: #ffffff;
          border: none;
          border-radius: 8px;
          font-size: 0.95rem;
          font-weight: 800;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 0.6rem;
          transition: all 0.25s ease;
          box-shadow: 0 4px 12px rgba(37, 99, 235, 0.22);
        }
        .primary-submit-btn:hover {
          background: #1D4ED8;
          transform: translateY(-1.5px);
          box-shadow: 0 6px 18px rgba(37, 99, 235, 0.32);
        }
        .primary-submit-btn:disabled {
          background: #94A3B8;
          cursor: not-allowed;
          transform: none;
          box-shadow: none;
        }
        .sso-btn {
          width: 100%;
          padding: 0.75rem 1.5rem;
          background: #ffffff;
          color: #0F172A;
          border: 1.5px solid #E5E7EB;
          border-radius: 8px;
          font-size: 0.88rem;
          font-weight: 700;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 0.5rem;
          transition: all 0.2s ease;
        }
        .sso-btn:hover {
          background: #F1F5F9;
          border-color: #CBD5E1;
        }
        @media (max-width: 1024px) {
          .split-container {
            flex-direction: column !important;
          }
          .left-branding-panel {
            width: 100% !important;
            padding: 2.5rem 1.75rem !important;
            min-height: auto !important;
          }
          .right-auth-panel {
            width: 100% !important;
            padding: 2.5rem 1.75rem !important;
          }
        }
      `}</style>

      <div className="split-container login-fade-in" style={{ display: 'flex', width: '100%', minHeight: '100vh' }}>

        {/* ==================================================== */}
        {/* LEFT PANEL (55%): INDUSTRIAL BRANDING & VISUAL IDENTITY */}
        {/* ==================================================== */}
        <div
          className="left-branding-panel"
          style={{
            width: '55%',
            background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 50%, #0F172A 100%)',
            padding: '4rem 4.5rem',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
            position: 'relative',
            overflow: 'hidden',
            color: '#ffffff',
          }}
        >
          {/* Subtle Industrial Grid Background Pattern */}
          <div
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundImage: `radial-gradient(rgba(37, 99, 235, 0.15) 1px, transparent 1px)`,
              backgroundSize: '28px 28px',
              pointerEvents: 'none',
              opacity: 0.6,
            }}
          />

          {/* Top Logo Branding */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.85rem', zIndex: 2 }}>
            <div
              style={{
                width: '44px',
                height: '44px',
                borderRadius: '10px',
